                \draw[fill=gray!12] (O) -- (V) -- (UV) -- (U) -- cycle;
                \draw[->, very thick] (O) -- (V) node[midway, left] {\(\mathbf v\)};
                \draw[->, very thick] (O) -- (U) node[midway, below] {\(\mathbf u\)};
